mkdir bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type        = string
  default     = "eu-north-1"
  description = "Region the state bucket and its encryption key are created in."
}

variable "state_bucket_name" {
  type        = string
  description = "Globally unique name of the S3 bucket that holds Terraform state. Choose a name that is not guessable from other public names."
}

variable "state_access_principal_arns" {
  type        = list(string)
  description = "IAM role or user ARNs allowed to read and write state objects and use the encryption key. Only these principals, plus the account root for key administration, can reach state."

  validation {
    condition     = length(var.state_access_principal_arns) > 0
    error_message = "At least one principal ARN is required."
  }
}
EOF
cat > main.tf <<'EOF'
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# State holds the uploader's secret access key in cleartext, so the bucket is
# encrypted with a customer-managed key whose use is limited to listed principals.
resource "aws_kms_key" "state" {
  description             = "Encrypts Terraform state objects"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "KeyAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "StateAccess"
        Effect    = "Allow"
        Principal = { AWS = var.state_access_principal_arns }
        Action    = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource  = "*"
      },
    ]
  })
}

resource "aws_kms_alias" "state" {
  name          = "alias/terraform-state"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "DenyAccessOutsideStatePrincipals"
    effect    = "Deny"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "ArnNotLike"
      variable = "aws:PrincipalArn"
      values   = var.state_access_principal_arns
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket_name" {
  description = "Name of the state bucket. Use it as `bucket` in the root configuration's backend config file."
  value       = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  description = "ARN of the key that encrypts state. Use it as `kms_key_id` in the root configuration's backend config file."
  value       = aws_kms_key.state.arn
}
EOF
cd ..
cat > backend.tf <<'EOF'
# Bucket and kms_key_id are supplied with `terraform init -backend-config=backend.hcl`
# (see backend.hcl.example). Locking uses an S3 lock object, so no DynamoDB table is needed.
terraform {
  backend "s3" {
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > backend.hcl.example <<'EOF'
# Copy to backend.hcl (git-ignored) and fill in from `terraform output` in bootstrap/.
bucket     = "<state_bucket_name>"
kms_key_id = "<state_kms_key_arn>"
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
crash.*.log
.terraformrc
terraform.rc
*.tfvars
*.auto.tfvars
backend.hcl
EOF
